//******************************************************
// set values for CANDataExtractionSkillThreshold
//******************************************************
void CarStudyRangeStudy::SetValues_CANDataExtractionSkillThreshold() {
  for (int n=0; n<NumExps; n++)
    CANDataExtractionSkillThresholdValues[n] = 250;
}


//******************************************************
// set values for CANExtractionCost
//******************************************************
void CarStudyRangeStudy::SetValues_CANExtractionCost() {
  for (int n=0; n<NumExps; n++)
    CANExtractionCostValues[n] = 2;
}


//******************************************************
// set values for CANSpoofingSkillThreshold
//******************************************************
void CarStudyRangeStudy::SetValues_CANSpoofingSkillThreshold() {
  for (int n=0; n<NumExps; n++)
    CANSpoofingSkillThresholdValues[n] = 350;
}


