//******************************************************
// set values for v2XPacketCraftingSkillThreshold
//******************************************************
void CarStudyRangeStudy::SetValues_v2XPacketCraftingSkillThreshold() {
  for (int n=0; n<NumExps; n++)
    v2XPacketCraftingSkillThresholdValues[n] = 300;
}



//******************************************************
//print values of gv (for debugging)
//******************************************************
void CarStudyRangeStudy::PrintGlobalValues(int expNum) {
  if (NumGVs == 0) {
    cout<<"There are no global variables."<<endl;
    return;
  }

  SetGVs(expNum);

  cout<<"The Global Variable values for experiment "<<
    GetExpName(expNum)<<" are:"<<endl;
  cout << "CANDataExtractionSkillThreshold\tshort\t" << CANDataExtractionSkillThreshold << endl;
  cout << "CANExtractionCost\tshort\t" << CANExtractionCost << endl;
  cout << "CANSpoofingSkillThreshold\tshort\t" << CANSpoofingSkillThreshold << endl;
  cout << "OEMImpersonationCost\tshort\t" << OEMImpersonationCost << endl;
  cout << "OEMSpoofingSkillThreshold\tshort\t" << OEMSpoofingSkillThreshold << endl;
  cout << "binaryInjectionCost\tshort\t" << binaryInjectionCost << endl;
  cout << "chipFlashingSkillLevel\tshort\t" << chipFlashingSkillLevel << endl;
  cout << "chipFlashingSkillThreshold\tshort\t" << chipFlashingSkillThreshold << endl;
  cout << "dataExtractionSkillLevel\tshort\t" << dataExtractionSkillLevel << endl;
  cout << "hasCarModelKnowledge\tbool\t" << hasCarModelKnowledge << endl;
  cout << "hasMessageFormatKnowledge\tbool\t" << hasMessageFormatKnowledge << endl;
  cout << "hasProximityNetworkAccess\tbool\t" << hasProximityNetworkAccess << endl;
  cout << "hasRemoteNetworkAccess\tbool\t" << hasRemoteNetworkAccess << endl;
  cout << "hasV2XProtocolKnowledge\tbool\t" << hasV2XProtocolKnowledge << endl;
  cout << "injectionSkillLevel\tshort\t" << injectionSkillLevel << endl;
  cout << "injectionSkillThreshold\tshort\t" << injectionSkillThreshold << endl;
  cout << "maliciousCANCost\tshort\t" << maliciousCANCost << endl;
  cout << "maliciousV2XCost\tshort\t" << maliciousV2XCost << endl;
  cout << "reflashChipCost\tshort\t" << reflashChipCost << endl;
  cout << "remoteDataExtractionThreshold\tshort\t" << remoteDataExtractionThreshold << endl;
  cout << "remoteExtractionCost\tshort\t" << remoteExtractionCost << endl;
  cout << "spoofingSkillLevel\tshort\t" << spoofingSkillLevel << endl;
  cout << "v2XPacketCraftingSkillLevel\tshort\t" << v2XPacketCraftingSkillLevel << endl;
  cout << "v2XPacketCraftingSkillThreshold\tshort\t" << v2XPacketCraftingSkillThreshold << endl;
}


//******************************************************
//retrieve the value of a global variable
//******************************************************
void *CarStudyRangeStudy::GetGVValue(char *TheGVName) {
  if (strcmp("CANDataExtractionSkillThreshold", TheGVName) == 0)
    return &CANDataExtractionSkillThreshold;
  else if (strcmp("CANExtractionCost", TheGVName) == 0)
    return &CANExtractionCost;
  else if (strcmp("CANSpoofingSkillThreshold", TheGVName) == 0)
    return &CANSpoofingSkillThreshold;
  else if (strcmp("OEMImpersonationCost", TheGVName) == 0)
    return &OEMImpersonationCost;
  else if (strcmp("OEMSpoofingSkillThreshold", TheGVName) == 0)
    return &OEMSpoofingSkillThreshold;
  else if (strcmp("binaryInjectionCost", TheGVName) == 0)
    return &binaryInjectionCost;
  else if (strcmp("chipFlashingSkillLevel", TheGVName) == 0)
    return &chipFlashingSkillLevel;
  else if (strcmp("chipFlashingSkillThreshold", TheGVName) == 0)
    return &chipFlashingSkillThreshold;
  else if (strcmp("dataExtractionSkillLevel", TheGVName) == 0)
    return &dataExtractionSkillLevel;
  else if (strcmp("hasCarModelKnowledge", TheGVName) == 0)
    return &hasCarModelKnowledge;
  else if (strcmp("hasMessageFormatKnowledge", TheGVName) == 0)
    return &hasMessageFormatKnowledge;
  else if (strcmp("hasProximityNetworkAccess", TheGVName) == 0)
    return &hasProximityNetworkAccess;
  else if (strcmp("hasRemoteNetworkAccess", TheGVName) == 0)
    return &hasRemoteNetworkAccess;
  else if (strcmp("hasV2XProtocolKnowledge", TheGVName) == 0)
    return &hasV2XProtocolKnowledge;
  else if (strcmp("injectionSkillLevel", TheGVName) == 0)
    return &injectionSkillLevel;
  else if (strcmp("injectionSkillThreshold", TheGVName) == 0)
    return &injectionSkillThreshold;
  else if (strcmp("maliciousCANCost", TheGVName) == 0)
    return &maliciousCANCost;
  else if (strcmp("maliciousV2XCost", TheGVName) == 0)
    return &maliciousV2XCost;
  else if (strcmp("reflashChipCost", TheGVName) == 0)
    return &reflashChipCost;
  else if (strcmp("remoteDataExtractionThreshold", TheGVName) == 0)
    return &remoteDataExtractionThreshold;
  else if (strcmp("remoteExtractionCost", TheGVName) == 0)
    return &remoteExtractionCost;
  else if (strcmp("spoofingSkillLevel", TheGVName) == 0)
    return &spoofingSkillLevel;
  else if (strcmp("v2XPacketCraftingSkillLevel", TheGVName) == 0)
    return &v2XPacketCraftingSkillLevel;
  else if (strcmp("v2XPacketCraftingSkillThreshold", TheGVName) == 0)
    return &v2XPacketCraftingSkillThreshold;
  else 
    cerr<<"!! CarStudyRangeStudy::GetGVValue: Global Variable "<<TheGVName<<" does not exist."<<endl;
  return NULL;
}


//******************************************************
//override the value of a global variable
//******************************************************
void CarStudyRangeStudy::OverrideGVValue(char *TheGVName,void *TheGVValue) {
  if (strcmp("CANDataExtractionSkillThreshold", TheGVName) == 0)
    SetGvValue(CANDataExtractionSkillThreshold, *(short *)TheGVValue);
  else if (strcmp("CANExtractionCost", TheGVName) == 0)
    SetGvValue(CANExtractionCost, *(short *)TheGVValue);
  else if (strcmp("CANSpoofingSkillThreshold", TheGVName) == 0)
    SetGvValue(CANSpoofingSkillThreshold, *(short *)TheGVValue);
  else if (strcmp("OEMImpersonationCost", TheGVName) == 0)
    SetGvValue(OEMImpersonationCost, *(short *)TheGVValue);
  else if (strcmp("OEMSpoofingSkillThreshold", TheGVName) == 0)
    SetGvValue(OEMSpoofingSkillThreshold, *(short *)TheGVValue);
  else if (strcmp("binaryInjectionCost", TheGVName) == 0)
    SetGvValue(binaryInjectionCost, *(short *)TheGVValue);
  else if (strcmp("chipFlashingSkillLevel", TheGVName) == 0)
    SetGvValue(chipFlashingSkillLevel, *(short *)TheGVValue);
  else if (strcmp("chipFlashingSkillThreshold", TheGVName) == 0)
    SetGvValue(chipFlashingSkillThreshold, *(short *)TheGVValue);
  else if (strcmp("dataExtractionSkillLevel", TheGVName) == 0)
    SetGvValue(dataExtractionSkillLevel, *(short *)TheGVValue);
  else if (strcmp("hasCarModelKnowledge", TheGVName) == 0)
    SetGvValue(hasCarModelKnowledge, *(bool *)TheGVValue);
  else if (strcmp("hasMessageFormatKnowledge", TheGVName) == 0)
    SetGvValue(hasMessageFormatKnowledge, *(bool *)TheGVValue);
  else if (strcmp("hasProximityNetworkAccess", TheGVName) == 0)
    SetGvValue(hasProximityNetworkAccess, *(bool *)TheGVValue);
  else if (strcmp("hasRemoteNetworkAccess", TheGVName) == 0)
    SetGvValue(hasRemoteNetworkAccess, *(bool *)TheGVValue);
  else if (strcmp("hasV2XProtocolKnowledge", TheGVName) == 0)
    SetGvValue(hasV2XProtocolKnowledge, *(bool *)TheGVValue);
  else if (strcmp("injectionSkillLevel", TheGVName) == 0)
    SetGvValue(injectionSkillLevel, *(short *)TheGVValue);
  else if (strcmp("injectionSkillThreshold", TheGVName) == 0)
    SetGvValue(injectionSkillThreshold, *(short *)TheGVValue);
  else if (strcmp("maliciousCANCost", TheGVName) == 0)
    SetGvValue(maliciousCANCost, *(short *)TheGVValue);
  else if (strcmp("maliciousV2XCost", TheGVName) == 0)
    SetGvValue(maliciousV2XCost, *(short *)TheGVValue);
  else if (strcmp("reflashChipCost", TheGVName) == 0)
    SetGvValue(reflashChipCost, *(short *)TheGVValue);
  else if (strcmp("remoteDataExtractionThreshold", TheGVName) == 0)
    SetGvValue(remoteDataExtractionThreshold, *(short *)TheGVValue);
  else if (strcmp("remoteExtractionCost", TheGVName) == 0)
    SetGvValue(remoteExtractionCost, *(short *)TheGVValue);
  else if (strcmp("spoofingSkillLevel", TheGVName) == 0)
    SetGvValue(spoofingSkillLevel, *(short *)TheGVValue);
  else if (strcmp("v2XPacketCraftingSkillLevel", TheGVName) == 0)
    SetGvValue(v2XPacketCraftingSkillLevel, *(short *)TheGVValue);
  else if (strcmp("v2XPacketCraftingSkillThreshold", TheGVName) == 0)
    SetGvValue(v2XPacketCraftingSkillThreshold, *(short *)TheGVValue);
  else 
    cerr<<"!! CarStudyRangeStudy::OverrideGVValue: Global Variable "<<TheGVName<<" does not exist."<<endl;
}


//******************************************************
//set the value of all global variables to the given exp
//******************************************************
void CarStudyRangeStudy::SetGVs(int expNum) {
  SetGvValue(CANDataExtractionSkillThreshold, CANDataExtractionSkillThresholdValues[expNum]);
  SetGvValue(CANExtractionCost, CANExtractionCostValues[expNum]);
  SetGvValue(CANSpoofingSkillThreshold, CANSpoofingSkillThresholdValues[expNum]);
  SetGvValue(OEMImpersonationCost, OEMImpersonationCostValues[expNum]);
  SetGvValue(OEMSpoofingSkillThreshold, OEMSpoofingSkillThresholdValues[expNum]);
  SetGvValue(binaryInjectionCost, binaryInjectionCostValues[expNum]);
  SetGvValue(chipFlashingSkillLevel, chipFlashingSkillLevelValues[expNum]);
  SetGvValue(chipFlashingSkillThreshold, chipFlashingSkillThresholdValues[expNum]);
  SetGvValue(dataExtractionSkillLevel, dataExtractionSkillLevelValues[expNum]);
  SetGvValue(hasCarModelKnowledge, hasCarModelKnowledgeValues[expNum]);
  SetGvValue(hasMessageFormatKnowledge, hasMessageFormatKnowledgeValues[expNum]);
  SetGvValue(hasProximityNetworkAccess, hasProximityNetworkAccessValues[expNum]);
  SetGvValue(hasRemoteNetworkAccess, hasRemoteNetworkAccessValues[expNum]);
  SetGvValue(hasV2XProtocolKnowledge, hasV2XProtocolKnowledgeValues[expNum]);
  SetGvValue(injectionSkillLevel, injectionSkillLevelValues[expNum]);
  SetGvValue(injectionSkillThreshold, injectionSkillThresholdValues[expNum]);
  SetGvValue(maliciousCANCost, maliciousCANCostValues[expNum]);
  SetGvValue(maliciousV2XCost, maliciousV2XCostValues[expNum]);
  SetGvValue(reflashChipCost, reflashChipCostValues[expNum]);
  SetGvValue(remoteDataExtractionThreshold, remoteDataExtractionThresholdValues[expNum]);
  SetGvValue(remoteExtractionCost, remoteExtractionCostValues[expNum]);
  SetGvValue(spoofingSkillLevel, spoofingSkillLevelValues[expNum]);
  SetGvValue(v2XPacketCraftingSkillLevel, v2XPacketCraftingSkillLevelValues[expNum]);
  SetGvValue(v2XPacketCraftingSkillThreshold, v2XPacketCraftingSkillThresholdValues[expNum]);
}


//******************************************************
//static class method called by solvers to create study 
//(and thus create all of the model)
//******************************************************
BaseStudyClass* GlobalStudyPtr = NULL;
BaseStudyClass * GenerateStudy() {
  if (GlobalStudyPtr == NULL)
    GlobalStudyPtr = new CarStudyRangeStudy();
  return GlobalStudyPtr;
}

void DestructStudy() {
  delete GlobalStudyPtr;
  GlobalStudyPtr = NULL;
}
//******************************************************
//get and create the PVModel
//******************************************************
PVModel* CarStudyRangeStudy::GetPVModel(bool expandTimeArrays) {
  if (ThePVModel!=NULL)
    delete ThePVModel;
  // create the PV model
  ThePVModel=new CarRewardPVModel(expandTimeArrays);
  return ThePVModel;
}


